from pathlib import Path
import hashlib,json,os,subprocess,sys,shutil,importlib.util,time
ROOT=Path(__file__).resolve().parents[2];INPUT=ROOT/'build/case-retained-input';OUT=ROOT/'build/compiler-pilot';OUT.mkdir(parents=True,exist_ok=True);D=OUT/'copied-case-trace1';D.mkdir()
sys.path.insert(0,str(ROOT/'tools'))
from compiler_profile import require_optimized
import sample_native_gate
def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,v):(D/n).write_text(json.dumps(v,indent=2)+'\n')
def git(*a):return subprocess.check_output(['git',*a],cwd=ROOT,text=True).strip()
candidate=git('rev-parse','HEAD');assert not git('status','--porcelain')
previous=json.loads((INPUT/'summary.json').read_text())['actual_producer'];assert previous['revision']=='3c9cfd4b5e2d143394d5f407d8b5a7f7bcd727cb'
inputs=json.loads((INPUT/'case-where-integrated1/source-inputs.json').read_text())['files']
frozen=ROOT/'build/verified-producer-source3c9';subprocess.run(['git','worktree','add','--detach',str(frozen),previous['revision']],cwd=ROOT,check=True)
assert all(h(frozen/p)==v for p,v in inputs.items())
spec=importlib.util.spec_from_file_location('case_frozen_owner',frozen/'tools/ci/compiler_pilot.py');owner=importlib.util.module_from_spec(spec);sys.modules[spec.name]=owner;spec.loader.exec_module(owner)
retained=OUT/'producer-copied-case-baseline';retained.mkdir();cli=retained/'omega';runner=retained/'corpus_runner'
for name in ['omega','corpus_runner','corpus_runner.compiler-profile.json']:shutil.copy2(INPUT/Path(previous['cli']).parent.name/name,retained/name)
for binary in [cli,runner]:binary.chmod(binary.stat().st_mode|0o111)
profile=require_optimized(cli);runner_profile=require_optimized(runner);assert profile['sha256']==previous['cli_profile']['sha256'] and runner_profile['sha256']==previous['runner_profile']['sha256'];producer=owner.CompilerProducer(previous['revision'],previous['tree'],previous['target'],previous['toolchain'],cli.resolve(),runner.resolve(),profile,runner_profile);producer.verify()
save('source-inputs.json',dict(candidate=candidate,actual_compiler_revision=producer.revision,files=inputs));(retained/'producer.json').write_text(json.dumps(producer.record(),indent=2)+'\n');(retained/'omega.verified-profile.json').write_text(json.dumps(dict(source_revision=producer.revision,source_tree=producer.tree,toolchain=producer.toolchain,observation=profile),indent=2)+'\n')
os.environ['OMEGA_LIBRARY_ROOT']=str(frozen/'source/library')

