os.environ['OMEGA_STRUCT_TRACE']='1'
records=[]
for label,fixture in [('nested-positive','pass/facts/copied_case_before_later_argument_through_other_state_exit'),('local-positive','pass/facts/copied_case_before_later_argument_through_local_exit'),('nested-absent','fail/facts/copied_case_before_later_argument_through_other_state_rejected')]:
 project=ROOT/'tests/omega'/fixture
 failure,review=sample_native_gate.accept_review(str(cli),str(project),producer.target,180);parts=[('review',review)]
 command=[str(cli),'--check','--target',producer.target,'--report-file',str(D/(label+'.report.txt')),str(project/'main.omg')]
 if failure:code=None
 else:
  r=subprocess.run(command,cwd=ROOT,capture_output=True,text=True,stdin=subprocess.DEVNULL,timeout=120);code=r.returncode;parts.append(('check',r.stdout+r.stderr))
 streams=[];selected=[]
 for phase,text in parts:
  raw=text.encode();to=D/(label+'.'+phase+'.raw.txt.gz');to.write_bytes(gzip.compress(raw));streams.append(dict(phase=phase,raw_bytes=len(raw),raw_sha256=hashlib.sha256(raw).hexdigest(),gzip_sha256=h(to),retained=to.name))
  selected.extend(line for line in text.splitlines() if any(x in line for x in ['PRIVATE arrivals','STRUCT runtime-prefix','STRUCT normal-capture','STRUCT case-domain','STRUCT case-guarantee','STRUCT call-entry','cannot prove requires']))
 (D/(label+'.selected.txt')).write_text('\n'.join(selected)+'\n');locks={}
 for name in ['omega.lock','omega.admissions']:
  p=project/name
  if p.is_file():to=D/(label+'.'+name+'.txt');shutil.copy2(p,to);locks[name]=dict(sha256=h(to),bytes=to.stat().st_size,retained=to.name)
 records.append(dict(label=label,fixture=fixture,command=command,returncode=code,refusal=failure,streams=streams,consumed_locks=locks,inputs={p.name:dict(sha256=h(p),text=p.read_text()) for p in project.iterdir() if p.is_file() and p.name in ['main.omg','build.omg','expected.txt','expected_native_exit.txt']}));save('observations.json',records)
